<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
saas_require_login();$orgId=saas_require_organization();$tourId=saas_require_tour();saas_require_permission('tour.edit');$db=saas_db();$tour=saas_current_tour();$org=saas_current_organization();$user=saas_current_user();$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$action=(string)($_POST['action']??'add');$id=(int)($_POST['id']??0);if($action==='delete'){ $q=$db->prepare('DELETE FROM incomes WHERE id=? AND tour_id=?');$q->execute([$id,$tourId]);saas_audit('income.deleted','income',$id);$ok='Income deleted.';}else{$cat=trim((string)($_POST['category']??''));$amount=round(max(0,(float)($_POST['amount']??0)),2);$from=trim((string)($_POST['received_from']??''));$desc=trim((string)($_POST['description']??''));$date=(string)($_POST['income_date']??date('Y-m-d'));if($cat==='')throw new RuntimeException('Income category is required.');if($amount<=0)throw new RuntimeException('Income amount must be greater than 0.');if($action==='update'){$q=$db->prepare('UPDATE incomes SET category=?,description=?,amount=?,received_from=?,income_date=? WHERE id=? AND tour_id=?');$q->execute([$cat,$desc,$amount,$from?:null,$date,$id,$tourId]);saas_audit('income.updated','income',$id);$ok='Income updated.';}else{$incomeOrgColumn=(int)$db->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='incomes' AND COLUMN_NAME='organization_id'")->fetchColumn()>0;if($incomeOrgColumn){$q=$db->prepare('INSERT INTO incomes(organization_id,tour_id,category,description,amount,received_from,income_date,created_by) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$orgId,$tourId,$cat,$desc,$amount,$from?:null,$date,saas_user_id()]);}else{$q=$db->prepare('INSERT INTO incomes(tour_id,category,description,amount,received_from,income_date,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$tourId,$cat,$desc,$amount,$from?:null,$date,saas_user_id()]);}$id=(int)$db->lastInsertId();saas_audit('income.created','income',$id);$ok='Income added.';}}}catch(Throwable $e){$error=$e->getMessage();}}
$editId=(int)($_GET['edit']??0);$edit=null;if($editId){$q=$db->prepare('SELECT * FROM incomes WHERE id=? AND tour_id=? LIMIT 1');$q->execute([$editId,$tourId]);$edit=$q->fetch()?:null;}
$q=$db->prepare('SELECT * FROM incomes WHERE tour_id=? ORDER BY income_date DESC,id DESC');$q->execute([$tourId]);$rows=$q->fetchAll();$total=0;foreach($rows as $r)$total+=(float)$r['amount'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Income — <?=saas_h($tour['name'])?> — GoTM</title><style>.income-grid{display:grid;grid-template-columns:380px minmax(0,1fr);gap:18px}.money-card{padding:16px;border:1px solid #e1eee6;border-radius:14px;background:#f8fcf9;margin-bottom:16px}.money-card small{color:#667085}.money-card strong{display:block;font-size:28px;margin-top:4px;color:#0b2a49}.field{margin-bottom:12px}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:9px;font:inherit;box-sizing:border-box}.field textarea{min-height:80px}.actions{display:flex;gap:8px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:720px}th,td{padding:11px;border-bottom:1px solid #edf0f2;text-align:left;font-size:12px}th{color:#667085;font-size:10px;text-transform:uppercase}.btn{display:inline-flex;align-items:center;justify-content:center;padding:9px 12px;border-radius:9px;border:1px solid #b8c4d0;background:#fff;text-decoration:none;font-weight:800;font-size:12px;cursor:pointer;box-shadow:0 1px 2px #0000000b}.export-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.export-btn{display:inline-flex!important;align-items:center;gap:6px;padding:9px 13px!important;border:1px solid #94a3b8!important;border-radius:9px!important;background:#fff!important;color:#0b2a49!important;box-shadow:0 2px 5px #00000012}.export-btn.pdf{border-color:#f0a800!important;background:#fff8e7!important;color:#8a5600!important}.export-btn.excel{border-color:#6bbf8a!important;background:#effbf3!important;color:#176b3a!important}.btn.primary{background:#f7ab17;border-color:#f7ab17;color:#0b2a49}.btn.danger{color:#b42318}@media(max-width:900px){.income-grid{grid-template-columns:1fr}} </style></head><body><main class="wrap"><div class="card"><div class="head"><div><div class="eyebrow">TOUR INCOME</div><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h1><?= $edit?'Edit Income':'Income' ?></h1><div class="export-actions"><a class="export-btn pdf" target="_blank" href="export.php?type=income&format=pdf">▣ Print / PDF</a><a class="export-btn excel" href="export.php?type=income&format=excel">▤ Export Excel</a></div></div><p class="muted">Record income outside passenger payments.</p></div><a class="btn" href="dashboard.php">Dashboard</a></div><?php if($ok):?><div class="alert"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="alert danger"><?=saas_h($error)?></div><?php endif;?></div><div class="income-grid"><section class="card"><div class="money-card"><small>Total other income</small><strong><?=number_format($total,2)?> BDT</strong></div><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="<?= $edit?'update':'add' ?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="field"><label>Category *</label><select name="category" required><?php foreach(['T-Shirt Sales','Donation','Sponsorship','Other Income'] as $cat):?><option value="<?=saas_h($cat)?>" <?=($edit['category']??'')===$cat?'selected':''?>><?=saas_h($cat)?></option><?php endforeach;?></select></div><div class="field"><label>Amount *</label><input type="number" step="0.01" min="0" name="amount" value="<?=saas_h($edit['amount']??'')?>" required></div><div class="field"><label>Received from</label><input name="received_from" value="<?=saas_h($edit['received_from']??'')?>" placeholder="Source / person"></div><div class="field"><label>Date</label><input type="date" name="income_date" value="<?=saas_h($edit['income_date']??date('Y-m-d'))?>" required></div><div class="field"><label>Description</label><textarea name="description" placeholder="Optional details"><?=saas_h($edit['description']??'')?></textarea></div><div class="actions"><button class="btn primary" type="submit"><?= $edit?'Update Income':'Save Income' ?></button><?php if($edit):?><a class="btn" href="income.php">Cancel</a><?php endif;?></div></form></section><section class="card"><div class="head"><div><h2>Income history</h2><p class="muted">All non-ticket income for this tour.</p></div></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Category</th><th>Received from</th><th>Description</th><th>Amount</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6">No income recorded yet.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=saas_h($r['income_date'])?></td><td><strong><?=saas_h($r['category'])?></strong></td><td><?=saas_h($r['received_from']??'—')?></td><td><?=saas_h($r['description']??'—')?></td><td><strong><?=number_format((float)$r['amount'],2)?></strong></td><td><div class="actions"><a class="btn" href="income.php?edit=<?=$r['id']?>">Edit</a><form method="post" style="display:inline" onsubmit="return confirm('Delete this income?')"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></main></body></html>